)

type Config struct {
	Environment environment.Environment `koanf:"environment"`
	DataDir     string                  `koanf:"data_dir"`
	Rest        *rest.Config            `koanf:"rest"`
	Postgres    *postgres.Config        `koanf:"postgres"`
	ContactForm *contact_form.Config    `koanf:"contact_form"`
	Auth        *auth.Config            `koanf:"auth"`
	Logger      *logger.Config          `koanf:"logger"`
}

func Load(envPath string) (*Config, error) {
	cfg := _default()

	koan := koanf.New(".")

	// Build global env->koanf key map using struct tags
	keyMap := buildEnvKeyMap(cfg)

	cb := func(key string) string {
		key = strings.TrimPrefix(key, "INFRA_")
		key = strings.ToLower(key)
		// Prefer mapped key if known (e.g., rest_enable_metrics_monitoring -> rest.enable_metrics_monitoring)
		if mapped, ok := keyMap[key]; ok {
			return mapped
		}
		// Fallback: structural conversion by replacing underscores with dots for hierarchy (best-effort)
		// e.g., REST_CORS_ALLOW_ORIGINS -> rest.cors.allow_origins
		parts := strings.Split(key, "_")

		return strings.Join(parts, ".")
	}

	if envPath != "" {
		if st, err := os.Stat(envPath); err == nil && !st.IsDir() {
			_ = koan.Load(file.Provider(envPath), dotenv.ParserEnv("INFRA_", ".", cb))
		}
	}

	if err := koan.Load(env.Provider("INFRA_", ".", cb), nil); err != nil {
		return nil, err
	}

	if err := koan.Unmarshal("", cfg); err != nil {
		return nil, err
	}

	return cfg, nil
}

func (c *Config) BasicCheck() error {
	if err := c.Rest.BasicCheck(); err != nil {
		return err
	}

	if err := c.Logger.BasicCheck(); err != nil {
		return err
	}

	if err := c.ContactForm.BasicCheck(); err != nil {
		return err
	}

	if err := c.Auth.BasicCheck(); err != nil {
		return err
	}

	return c.Postgres.BasicCheck()
}

func _default() *Config {
	return &Config{
		Environment: "development",
		DataDir:     "./data",
		Rest:        rest.DefaultConfig(),
		Logger:      logger.DefaultConfig(),
		Postgres:    postgres.DefaultConfig(),
		ContactForm: contact_form.DefaultConfig(),
		Auth:        auth.DefaultConfig(),
	}
}

// buildEnvKeyMap builds a map of env-style keys (with underscores) to koanf keys (with dots)
// by walking the Config struct and reading `koanf` struct tags.
// Example mapping:
//
//	rest_enable_metrics_monitoring -> rest.enable_metrics_monitoring
//	rest_cors_allow_origins        -> rest.cors.allow_origins
//	rest_rate_limit_max_requests   -> rest.rate_limit.max_requests
//	postgres_host                  -> postgres.host
//	logger_levels_rest             -> logger.levels_rest
//
// Top-level fields like environment, data_dir are also included.
func buildEnvKeyMap(cfg *Config) map[string]string {
	mp := make(map[string]string)

	// helper to walk any struct and record keys
	var walk func(prefixDot, prefixUnderscore string, val reflect.Value)
	walk = func(prefixDot, prefixUnderscore string, val reflect.Value) {
		if val.Kind() == reflect.Pointer {
			if val.IsNil() {
				return
			}
			val = val.Elem()
		}
		if val.Kind() != reflect.Struct {
			return
		}

		t := val.Type()
		for i := 0; i < t.NumField(); i++ {
			f := t.Field(i)
			koTag := f.Tag.Get("koanf")
			if koTag == "-" || koTag == "" {
				continue
			}

			var dotKey, underKey string
			if prefixDot == "" {
				dotKey = koTag
				underKey = koTag
			} else {
				dotKey = prefixDot + "." + koTag
				underKey = prefixUnderscore + "_" + koTag
			}

			mp[strings.ToLower(underKey)] = strings.ToLower(dotKey)

			// Recurse into nested structs/pointers
			fv := val.Field(i)
			walk(dotKey, underKey, fv)
		}
	}

	// Top-level: environment, data_dir
	rootVal := reflect.ValueOf(cfg).Elem()
	walk("", "", rootVal)

	return mp
}

