type JWT struct {
	signingKey     []byte
	accessTokenTTL time.Duration
	issuer         string
	audience       string
}

type Claim struct {
	jwt.RegisteredClaims

	UserID      string `json:"user_id"`
	SessionID   string `json:"session_id"`
	KycVerified bool   `json:"kyc_verified,omitempty"`
	KybVerified bool   `json:"kyb_verified,omitempty"`
	Role        string `json:"role"`
	Type        string `json:"type"`
}

func New(cfg *Config) (*JWT, error) {
	signingKey, err := base64.StdEncoding.DecodeString(cfg.SigningKey)
	if err != nil {
		return nil, fmt.Errorf("failed to decode signing key: %w", err)
	}

	return &JWT{
		signingKey:     signingKey,
		accessTokenTTL: cfg.AccessTokenTTL,
		issuer:         cfg.Issuer,
		audience:       cfg.Audience,
	}, nil
}

func (j *JWT) GenerateAccessToken(claim Claim) (string, error) {
	claim.ExpiresAt = jwt.NewNumericDate(time.Now().Add(j.accessTokenTTL))
	claim.Issuer = j.issuer
	claim.Audience = jwt.ClaimStrings{j.audience}
	token := jwt.NewWithClaims(jwt.SigningMethodHS256, claim)

	return token.SignedString(j.signingKey)
}

func (j *JWT) VerifyAccessToken(token string) (*Claim, error) {
	parsed, err := jwt.ParseWithClaims(token, &Claim{}, func(t *jwt.Token) (any, error) {
		if _, ok := t.Method.(*jwt.SigningMethodHMAC); !ok {
			return nil, fmt.Errorf("unexpected signing method: %v", t.Header["alg"])
		}

		return j.signingKey, nil
	})
	if err != nil {
		if errors.Is(err, jwt.ErrTokenExpired) {
			return nil, ErrTokenExpired
		}
		if errors.Is(err, jwt.ErrSignatureInvalid) {
			return nil, ErrTokenSignatureInvalid
		}

		return nil, ErrTokenInvalid
	}
	claims, ok := parsed.Claims.(*Claim)
	if !ok {
		return nil, ErrTokenClaimsMissing
	}

	return claims, nil
}

