# ==================================================================================== #
# VARIABLES
# ==================================================================================== #

## Application
APP_NAME = infrafund
BUILD_DIR = ./build
MAIN_PATH = ./cmd/api
DOCKER_IMAGE_NAME ?= infrafund-api
DOCKER_FILE = deployment/Dockerfile

## Build info
VERSION ?= $(shell git describe --tags --always --dirty 2>/dev/null || echo "dev")
COMMIT_HASH = $(shell git rev-parse --short HEAD 2>/dev/null || echo "unknown")
BUILD_TIME = $(shell date -u '+%Y-%m-%d_%H:%M:%S')
LDFLAGS = -ldflags "-X github.com/InfraFund-net7/backpro/version.GitCommit=$(COMMIT_HASH)"

## Tools versions
GOFUMPT_VERSION = latest
GOLANGCI_LINT_VERSION = latest
MOCKERY_VERSION = v3.6.1
SQLC_VERSION = latest
GOSEC_VERSION = latest
GOMIGRATE_VERSION = latest

## Test configuration
TEST_TIMEOUT = 10m
INTEGRATION_TEST_TIMEOUT = 15m
COVERAGE_FILE = coverage.out
COVERAGE_HTML = coverage.html

## Colors for output
COLOR_RESET = \033[0m
COLOR_BOLD = \033[1m
COLOR_GREEN = \033[32m
COLOR_YELLOW = \033[33m
COLOR_BLUE = \033[34m

# ==================================================================================== #
# HELPERS
# ==================================================================================== #

.PHONY: help
help: ## Display this help message
	@echo "$(COLOR_BOLD)InfraFund API - Makefile Commands$(COLOR_RESET)"
	@echo ""
	@grep -E '^[a-zA-Z_-]+:.*?## .*$$' $(MAKEFILE_LIST) | sort | awk 'BEGIN {FS = ":.*?## "}; {printf "$(COLOR_GREEN)%-25s$(COLOR_RESET) %s\n", $$1, $$2}'

.PHONY: confirm
confirm: ## Prompt for confirmation
	@echo -n "Are you sure? [y/N] " && read ans && [ $${ans:-N} = y ]

# ==================================================================================== #
# SETUP & INSTALLATION
# ==================================================================================== #

.PHONY: setup
setup: devtools deps init-env ## Complete development environment setup
	@echo "$(COLOR_GREEN)✓ Development environment ready!$(COLOR_RESET)"

.PHONY: devtools
devtools: install-gofumpt install-golangci-lint install-mockery install-sqlc install-migrate install-gosec ## Install all development tools
	@echo "$(COLOR_GREEN)✓ All dev tools installed!$(COLOR_RESET)"

.PHONY: install-gofumpt
install-gofumpt: ## Install gofumpt for code formatting
	@echo "$(COLOR_BLUE)→ Installing gofumpt...$(COLOR_RESET)"
	@go install mvdan.cc/gofumpt@$(GOFUMPT_VERSION)
	@echo "$(COLOR_GREEN)✓ gofumpt installed$(COLOR_RESET)"

.PHONY: install-golangci-lint
install-golangci-lint: ## Install golangci-lint for code linting
	@echo "$(COLOR_BLUE)→ Installing golangci-lint...$(COLOR_RESET)"
	@go install github.com/golangci/golangci-lint/v2/cmd/golangci-lint@$(GOLANGCI_LINT_VERSION)
	@echo "$(COLOR_GREEN)✓ golangci-lint installed$(COLOR_RESET)"

.PHONY: install-mockery
install-mockery: ## Install mockery for mock generation
	@echo "$(COLOR_BLUE)→ Installing mockery...$(COLOR_RESET)"
	@go install github.com/vektra/mockery/v3@$(MOCKERY_VERSION)
	@echo "$(COLOR_GREEN)✓ mockery installed$(COLOR_RESET)"

.PHONY: install-sqlc
install-sqlc: ## Install sqlc for SQL code generation
	@echo "$(COLOR_BLUE)→ Installing sqlc...$(COLOR_RESET)"
	@go install github.com/sqlc-dev/sqlc/cmd/sqlc@$(SQLC_VERSION)
	@echo "$(COLOR_GREEN)✓ sqlc installed$(COLOR_RESET)"

.PHONY: install-migrate
install-migrate: ## Install go-migrate for database migrations
	@echo "$(COLOR_BLUE)→ Installing go-migrate...$(COLOR_RESET)"
	@go install -tags 'postgres' github.com/golang-migrate/migrate/v4/cmd/migrate@$(GOMIGRATE_VERSION)
	@echo "$(COLOR_GREEN)✓ go-migrate installed$(COLOR_RESET)"

.PHONY: install-gosec
install-gosec: ## Install gosec for security scanning
	@echo "$(COLOR_BLUE)→ Installing gosec...$(COLOR_RESET)"
	@go install github.com/securego/gosec/v2/cmd/gosec@$(GOSEC_VERSION)
	@echo "$(COLOR_GREEN)✓ gosec installed$(COLOR_RESET)"

.PHONY: deps
deps: ## Download Go module dependencies
	@echo "$(COLOR_BLUE)→ Downloading dependencies...$(COLOR_RESET)"
	@go mod download
	@go mod verify
	@echo "$(COLOR_GREEN)✓ Dependencies downloaded$(COLOR_RESET)"

.PHONY: deps-update
deps-update: confirm ## Update Go module dependencies
	@echo "$(COLOR_BLUE)→ Updating dependencies...$(COLOR_RESET)"

	@go get -u ./...
	@go mod tidy
	@echo "$(COLOR_GREEN)✓ Dependencies updated$(COLOR_RESET)"

.PHONY: init-env
init-env: confirm ## Initialize .env file from .env.example
	@if [ ! -f .env ]; then \
		echo "$(COLOR_BLUE)→ Creating .env from .env.example...$(COLOR_RESET)"; \
		cp .env.example .env; \
		echo "$(COLOR_YELLOW)⚠ Please update .env with your configuration$(COLOR_RESET)"; \
	else \
		echo "$(COLOR_YELLOW)⚠ .env already exists, skipping$(COLOR_RESET)"; \
	fi

# ==================================================================================== #
# CODE GENERATION
# ==================================================================================== #

.PHONY: generate
generate: sqlc mock  ## Run all code generation tasks
	@echo "$(COLOR_GREEN)✓ All code generation complete$(COLOR_RESET)"

.PHONY: sqlc
sqlc: ## Generate code from SQL queries using sqlc
	@if ! command -v sqlc >/dev/null 2>&1; then \
		echo "$(COLOR_YELLOW)⚠ sqlc not found, installing...$(COLOR_RESET)"; \
		$(MAKE) install-sqlc; \
	fi
	@echo "$(COLOR_BLUE)→ Generating SQLC code...$(COLOR_RESET)"
	@sqlc generate
	@echo "$(COLOR_GREEN)✓ SQLC generation complete$(COLOR_RESET)"

.PHONY: migration-up migration-down create-migration migration-ver migration-force
create-migration:
	@read -p "Enter migration name: " name; \
	if [ -z "$$name" ]; then \
		echo "$(COLOR_YELLOW)⚠ Migration name cannot be empty$(COLOR_RESET)"; \
		exit 1; \
	fi; \
	echo "$(COLOR_BLUE)→ Creating migration: $$name...$(COLOR_RESET)"; \
	migrate create -ext sql -dir internal/infrastructure/persistence/postgres/migrations $$name; \
	echo "$(COLOR_GREEN)✓ Migration created$(COLOR_RESET)"

migration-up: ## Apply all up migrations to the database
	@echo "$(COLOR_BLUE)→ Applying migrations...$(COLOR_RESET)"
	@migrate -path internal/infrastructure/persistence/postgres/migrations -database "$$DATABASE_URL" up
	@echo "$(COLOR_GREEN)✓ Migrations applied$(COLOR_RESET)"

migration-force: ## Apply all up migrations to the database forcefully
	@read -p "Enter migration version: " ver; \
	if [ -z "$$ver" ]; then \
		echo "$(COLOR_YELLOW)⚠ Migration version cannot be empty$(COLOR_RESET)"; \
		exit 1; \
	fi; \
	echo "$(COLOR_BLUE)→ Forcing migration to version $$ver...$(COLOR_RESET)"; \
	migrate -path internal/infrastructure/persistence/postgres/migrations -database "$$DATABASE_URL" force $$ver; \
	echo "$(COLOR_GREEN)✓ Migration forced$(COLOR_RESET)"

migration-down: confirm ## Rollback last migration from the database
	@echo "$(COLOR_BLUE)→ Rolling back last migration...$(COLOR_RESET)"
	@migrate -path internal/infrastructure/persistence/postgres/migrations -database "$$DATABASE_URL" down 1
	@echo "$(COLOR_GREEN)✓ Migration rolled back$(COLOR_RESET)"

migration-ver: ## Show current migration version
	@echo "$(COLOR_BLUE)→ Current migration version:$(COLOR_RESET)"
	@migrate -path internal/infrastructure/persistence/postgres/migrations -database "$$DATABASE_URL" version

.PHONY: mock
mock: ## Generate test mocks using mockery
	@if ! command -v mockery >/dev/null 2>&1; then \
		echo "$(COLOR_YELLOW)⚠ mockery not found, installing...$(COLOR_RESET)"; \
		$(MAKE) install-mockery; \
	fi
	@echo "$(COLOR_BLUE)→ Generating mocks...$(COLOR_RESET)"
	@mkdir -p tests/mocks
	@mockery
	@echo "$(COLOR_GREEN)✓ Mock generation complete$(COLOR_RESET)"

