import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"runtime/debug"
	"strings"
	"time"

	"github.com/InfraFund-net7/backpro/internal/common/types/key"
	"github.com/InfraFund-net7/backpro/internal/interfaces/rest/middleware"
	"github.com/InfraFund-net7/backpro/internal/interfaces/rest/output"
	"github.com/InfraFund-net7/backpro/pkg/errs"
	"github.com/InfraFund-net7/backpro/pkg/logger"
	"github.com/InfraFund-net7/backpro/pkg/readiness"
	"github.com/danielgtaylor/huma/v2"
	"github.com/danielgtaylor/huma/v2/adapters/humafiber"
	"github.com/gofiber/fiber/v2"
	"github.com/gofiber/fiber/v2/middleware/compress"
	"github.com/gofiber/fiber/v2/middleware/cors"
	"github.com/gofiber/fiber/v2/middleware/encryptcookie"
	"github.com/gofiber/fiber/v2/middleware/healthcheck"
	"github.com/gofiber/fiber/v2/middleware/helmet"
	"github.com/gofiber/fiber/v2/middleware/monitor"
	"github.com/gofiber/fiber/v2/middleware/pprof"
	"github.com/gofiber/fiber/v2/middleware/recover"
	"github.com/gofiber/fiber/v2/middleware/requestid"
	"github.com/google/uuid"
	"github.com/ja7ad/captcha"
	"go.uber.org/fx"
)

type Rest struct {
	app      *fiber.App
	api      huma.API
	rcap     captcha.Captcha
	readyMgr *readiness.Manager
	cfg      *Config
	dataDir  string
	logging  *logger.SubLogger
}

func New(lc fx.Lifecycle, cfg *Config, readyMgr *readiness.Manager, dataDir string) *Rest {
	app := fiber.New(fiber.Config{
		DisableStartupMessage: cfg.DisableStartupMessage,
		ReadTimeout:           cfg.ReadTimeout,
		WriteTimeout:          cfg.WriteTimeout,
		AppName:               "InfraFund API",
		ServerHeader:          "InfraFund",
		JSONEncoder:           json.Marshal,
		JSONDecoder:           json.Unmarshal,
	})

	srv := &Rest{
		dataDir:  dataDir,
		app:      app,
		cfg:      cfg,
		readyMgr: readyMgr,
		logging:  logger.NewRestLogger("fiber"),
	}

	apiCfg := huma.DefaultConfig("Infrafund API", "1.0")
	apiCfg.Info.Description = description
	apiCfg.Info.TermsOfService = "https://infurafund.net/terms"

	apiCfg.Info.Contact = &huma.Contact{
		Name:  "Infurafund",
		URL:   "https://infurafund.net",
		Email: "info@infurafund.net",
	}

	apiCfg.Servers = []*huma.Server{
		{
			URL:         "http://localhost:" + cfg.Port,
			Description: "Local",
		},
		{
			URL:         "https://api-dev.infrafund.net",
			Description: "Development",
		},
		{
			URL:         "https://api.infrafund.net",
			Description: "Production",
		},
	}

	apiCfg.Components.SecuritySchemes = map[string]*huma.SecurityScheme{
		"BearerAuth": {
			Type:         "http",
			Scheme:       "bearer",
			BearerFormat: "JWT",
		},
	}

	if !cfg.Development {
		apiCfg.DocsPath = ""
		apiCfg.SchemasPath = ""
		apiCfg.OpenAPIPath = ""
		srv.logging.Info("API documentation disabled in production mode")
	} else {
		srv.logging.Info("API documentation enabled in development mode", "docs_path", apiCfg.DocsPath)
	}

	srv.api = humafiber.New(app, apiCfg)

	srv.init()

	lc.Append(fx.Hook{
		OnStart: func(ctx context.Context) error {
			srv.logging.Info("Starting server", "port", srv.cfg.Port)

			errChan := make(chan error, 1)
			go func() {
				if err := srv.app.Listen(":" + srv.cfg.Port); err != nil {
					srv.logging.Error("Failed to start server", "error", err)
					errChan <- err
				}
			}()

			// Wait briefly to ensure server starts or fails
			select {
			case err := <-errChan:
				return err
			case <-time.After(100 * time.Millisecond):
				srv.logging.Info("Server started successfully")

				return nil
			case <-ctx.Done():
				return ctx.Err()
			}
		},
		OnStop: func(ctx context.Context) error {
			srv.logging.Warn("Shutting down server")

			return srv.app.ShutdownWithContext(ctx)
		},
	})

	return srv
}

func (r *Rest) App() *fiber.App {
	return r.app
}

func (r *Rest) ReCaptcha() captcha.Captcha {
	return r.rcap
}

func (r *Rest) API() huma.API {
	return r.api
}

func (r *Rest) init() {
	// Ensure storage directories exist
	limiterPath := filepath.Join(r.dataDir, "storage", "limiter")

	if err := os.MkdirAll(limiterPath, 0o750); err != nil {
		panic(fmt.Sprintf("failed to create limiter storage directory: %v", err))
	}

	r.api.UseMiddleware(middleware.ClientInfo)

	if r.cfg.EnableReadinessCheck {
		r.app.Get("/ready", func(c *fiber.Ctx) error {
			return c.JSON(r.readyMgr.CheckAll(c.UserContext()))
		})
	}

	if r.cfg.EnableHealthCheck {
		r.app.Use(healthcheck.New(healthcheck.Config{
			LivenessEndpoint: "/health",
		}))
		r.logging.Debug("healthcheck enabled", "addr", "/health")
	}

	if r.cfg.EnableMetricsMonitoring {
		r.app.Get("/usage", monitor.New(monitor.Config{Title: "Monitoring Infrafund"}))
		r.logging.Debug("metrics monitoring enabled", "addr", "/usage")
	}

	// Security headers - conditionally enabled
	if r.cfg.EnableHelmet {
		r.app.Use(helmet.New())
		r.logging.Debug("helmet enabled")
	}

	// Compression - conditionally enabled
	if r.cfg.EnableCompressRequestBody {
		r.app.Use(compress.New(compress.Config{
			Level: compress.LevelBestSpeed,
		}))
		r.logging.Debug("request body compression enabled")
	}

	// PProf profiling - conditionally enabled
	if r.cfg.EnablePProf {
		r.app.Use(pprof.New(pprof.Config{
			Next: func(ctx *fiber.Ctx) bool {
				return ctx.Path() == "/debug/pprof/cmdline"
			},
		}))
		r.logging.Debug("pprof enabled", "addr", "/debug/pprof")
	}

	r.app.Use(middleware.Logger(r.logging))

	// Recover from panics
	r.app.Use(recover.New(recover.Config{
		EnableStackTrace: true,
		StackTraceHandler: func(ctx *fiber.Ctx, err any) {
			var reqID string
			if val := ctx.Context().Value("request_id"); val != nil {
				if str, ok := val.(string); ok {
					reqID = str
				}
			}

			stackTrace := string(debug.Stack())
			// Split stack trace into lines for better formatting
			stackLines := strings.Split(stackTrace, "\n")
			var formattedStack strings.Builder
			for i, line := range stackLines {
				if i > 0 {
					formattedStack.WriteString("\n    ")
				}
				formattedStack.WriteString(strings.TrimSpace(line))
			}

			r.logging.Error("panic recovered",
				"error", err,
				"method", ctx.Method(),
				"path", ctx.OriginalURL(),
				"request_id", reqID,
				"stack", stackTrace,
			)

			resp := output.NewErrorOutput(errs.NewInternalError("internal server error"))
			if err := ctx.Status(fiber.StatusInternalServerError).JSON(resp); err != nil {
				r.logging.Error("failed to send panic output", "error", err)
			}
		},
	}))

	// Request ID
	r.app.Use(requestid.New(requestid.Config{
		Header:     "X-Request-ID",
		ContextKey: key.RequestIDKey,
		Generator: func() string {
			return uuid.New().String()
		},
	}))

	// CORS
	corsCfg := cors.Config{
		AllowOrigins:     strings.Join(r.cfg.Cors.AllowOrigins, ","),
		AllowCredentials: true,
		AllowMethods:     strings.Join(r.cfg.Cors.AllowMethods, ","),
		AllowHeaders:     strings.Join(r.cfg.Cors.AllowHeaders, ","),
		ExposeHeaders:    "Content-Length,X-Request-ID,X-Refresh-Token",
	}

	for _, origin := range r.cfg.Cors.AllowOrigins {
		if origin == "*" {
			corsCfg.AllowCredentials = false
		}
	}

	r.app.Use(cors.New(corsCfg))

	if len(r.cfg.CookieEncryptionSecretKey) >= 32 {
		r.app.Use(encryptcookie.New(encryptcookie.Config{
			Key: r.cfg.CookieEncryptionSecretKey,
		}))
		r.logging.Debug("cookie encryption enabled")
	}

	if r.cfg.Recaptcha.GoogleSecret != "" {
		r.rcap, _ = captcha.New(captcha.GoogleProvider, r.cfg.Recaptcha.GoogleSecret)
	}

	if r.cfg.Recaptcha.HCaptchaSecret != "" {
		r.rcap, _ = captcha.New(captcha.HCaptchaProvider, r.cfg.Recaptcha.HCaptchaSecret)
	}

	if r.cfg.Recaptcha.CloudflareSecret != "" {
		r.rcap, _ = captcha.New(captcha.CloudflareProvider, r.cfg.Recaptcha.CloudflareSecret)
	}
}

