func (a *AuthService) Register(ctx context.Context, req *dto.RegistrationReq) (*dto.LoginResp, error) {
	if err := a.validateNewUser(ctx, req); err != nil {
		return nil, err
	}

	particleUserInfo, err := a.particle.GetUserInfo(ctx, req.UUID, req.Token)
	if err != nil {
		a.logger.Error("failed to get particle user info", "error", err.Error())

		return nil, errs.NewAppError(errs.BadRequest,
			"Your particle ID and Token is invalid.", 400)
	}

	var (
		userID       uuid.UUID
		sessionID    uuid.UUID
		refreshToken string
		accessToken  string
	)

	if err = a.txn.WithinTransaction(ctx, func(ctx context.Context) error {
		userID, err = a.userRepo.Create(ctx, &userentity.User{
			OpenfortUserID: req.UUID,
			ParticleID:     req.UUID,
			Email:          req.Email,
			FirstName:      req.FirstName,
			LastName:       req.LastName,
			PhoneNumber:    req.PhoneNumber,
			CompanyName:    req.OrganizationName,
			Type:           req.Type,
			Role:           req.Role,
		})
		if err != nil {
			a.logger.Error("failed to create user",
				"error", err.Error(),
				"particle_uuid", req.UUID,
			)

			return errs.NewAppError(errs.Database, "Failed to create user", 500)
		}

		if req.Type == object.UserTypeOrganization {
			if err = a.userRepo.CreateOrganization(ctx, &userentity.Organization{
				UserID: userID,
				Name:   req.OrganizationName,
			}); err != nil {
				a.logger.Error("failed to create organization",
					"error", err.Error(),
					"particle_uuid", req.UUID,
				)

				return errs.NewAppError(errs.Database, "Failed to create user organization", 500)
			}
		}

		if err = a.createWallet(ctx, userID, particleUserInfo.Wallets); err != nil {
			a.logger.Error("failed to create wallet",
				"error", err.Error(),
				"particle_uuid", req.UUID,
			)

			return errs.NewAppError(errs.Database, "Failed to create wallet", 500)
		}

		sessionID, refreshToken, err = a.createSession(ctx, userID, req.Audit)
		if err != nil {
			return err
		}

		accessToken, err = a.createToken(userID, sessionID, false, false, req.Type, req.Role)
		if err != nil {
			a.logger.Error("failed to create token", "error", err.Error())

			return err
		}

		return nil
	}); err != nil {
		return nil, errs.NewAppError(errs.Database, "Failed to create user.", 500)
	}

	return &dto.LoginResp{
		UserID:             userID,
		AccessToken:        accessToken,
		RefreshToken:       refreshToken,
		AccessTokenExpiry:  time.Now().Add(a.cfg.Jwt.AccessTokenTTL),
		RefreshTokenExpiry: time.Now().Add(a.cfg.AbsoluteExpiresDuration),
	}, nil
}

func (a *AuthService) Login(ctx context.Context, req *dto.LoginReq) (*dto.LoginResp, error) {
	user, err := a.userRepo.GetByParticleID(ctx, req.UUID)
	if err != nil {
		if errs.IsNotFoundError(err) {
			return nil, errs.NewAppError(errs.NotFound,
				"Particle user not found, please try to registration.", 404)
		}

		a.logger.Error("failed to get user", "error", err.Error())

		return nil, errs.NewAppError(errs.Database,
			"Failed to get user.", 500)
	}

	if err = a.lockoutSvc.CheckAccountLock(ctx, user.ID); err != nil {
		a.logger.Warn("login attempt on locked account",
			"particle_uuid", req.UUID,
		)

		return nil, errs.NewAppError(errs.TooManyRequests, "Account locked. Try again later.", 429)
	}

	_, err = a.particle.GetUserInfo(ctx, req.UUID, req.Token)
	if err != nil {
		a.logger.Error("failed to get particle user info", "error", err.Error())

		if err = a.lockoutSvc.RecordFailedAttempt(
			ctx,
			user.ID,
			"LOGIN_FAILED",
		); err != nil {
			a.logger.Error("failed to record lockout attempt",
				"error", err.Error(),
				"user_id", user.ID,
			)
		}

		return nil, errs.NewAppError(errs.BadRequest,
			"Invalid particle user id or token.", 400)
	}

	sessID, rt, err := a.createSession(ctx, user.ID, req.Audit)
	if err != nil {
		a.logger.Error("failed to create session", "error", err.Error())

		return nil, errs.NewAppError(errs.Database, "Failed to create session.", 500)
	}

	accessToken, err := a.createToken(user.ID, sessID, user.KycVerified, user.KybVerified, user.Type, user.Role)
	if err != nil {
		a.logger.Error("failed to create token", "error", err.Error())

		return nil, errs.NewAppError(errs.Internal,
			"Failed to create access token.", 500)
	}

	if err = a.lockoutSvc.ResetAfterSuccessfulAuth(ctx, user.ID); err != nil {
		a.logger.Warn("failed to reset lockout after successful login",
			"error", err.Error(),
			"user_id", user.ID,
		)
	}

	return &dto.LoginResp{
		UserID:             user.ID,
		AccessToken:        accessToken,
		RefreshToken:       rt,
		AccessTokenExpiry:  time.Now().Add(a.cfg.Jwt.AccessTokenTTL),
		RefreshTokenExpiry: time.Now().Add(a.cfg.AbsoluteExpiresDuration),
	}, nil
}

func (a *AuthService) Exchange(ctx context.Context, req *dto.OpenfortExchangeReq) (*dto.LoginResp, error) {
	session, err := a.openfort.GetSession(ctx, req.AccessToken)
	if err != nil {
		a.logger.Error("failed to validate openfort session", "error", err.Error())

		return nil, errs.NewAppError(errs.Unauthorized, "Invalid Openfort access token.", 401)
	}

	user, created, err := a.findOrCreateUser(ctx, req, session)
	if err != nil {
		return nil, err
	}

	if !created {
		if err = a.lockoutSvc.CheckAccountLock(ctx, user.ID); err != nil {
			a.logger.Warn("openfort exchange attempt on locked account", "user_id", user.ID)

			return nil, errs.NewAppError(errs.TooManyRequests, "Account locked. Try again later.", 429)
		}
	}

	sessID, rt, err := a.createSession(ctx, user.ID, req.Audit)
	if err != nil {
		a.logger.Error("failed to create session", "error", err.Error())

		return nil, errs.NewAppError(errs.Database, "Failed to create session.", 500)
	}

	accessToken, err := a.createToken(user.ID, sessID, user.KycVerified, user.KybVerified, user.Type, user.Role)
	if err != nil {
		a.logger.Error("failed to create token", "error", err.Error())

		return nil, errs.NewAppError(errs.Internal, "Failed to create access token.", 500)
	}

	if !created {
		if err = a.lockoutSvc.ResetAfterSuccessfulAuth(ctx, user.ID); err != nil {
			a.logger.Warn("failed to reset lockout after successful exchange",
				"error", err.Error(),
				"user_id", user.ID,
			)
		}
	}

	return &dto.LoginResp{
		UserID:             user.ID,
		AccessToken:        accessToken,
		RefreshToken:       rt,
		AccessTokenExpiry:  time.Now().Add(a.cfg.Jwt.AccessTokenTTL),
		RefreshTokenExpiry: time.Now().Add(a.cfg.AbsoluteExpiresDuration),
	}, nil
}

