package auth

import (
	"context"
	"fmt"
	"strconv"
	"time"

	"github.com/InfraFund-net7/backpro/internal/application/auth/dto"
	"github.com/InfraFund-net7/backpro/internal/domain/session/entity"
	userentity "github.com/InfraFund-net7/backpro/internal/domain/user/entity"
	"github.com/InfraFund-net7/backpro/internal/domain/user/object"
	"github.com/InfraFund-net7/backpro/pkg/errs"
)

func (a *AuthService) validateNewUser(ctx context.Context, req *dto.RegistrationReq) error {
	if req.Type == object.UserTypeOrganization && req.OrganizationName == "" {
		return errs.NewAppError(errs.BadRequest, "Organization name is required.", 400)
	}

	if ok, err := a.userRepo.ExistsEmail(ctx, req.Email); err != nil || ok {
		if ok {
			return errs.NewAppError(errs.Conflict, "Email already in use, please try to login.", 409)
		}
		a.logger.Error("failed to check email existence", "error", err)

		return errs.NewAppError(errs.Database, "Failed to check email existence.", 500)
	}

	if ok, err := a.userRepo.ExistsPhone(ctx, req.PhoneNumber); err != nil || ok {
		if ok {
			return errs.NewAppError(errs.Conflict, "Phone number already in use, please try to login.", 409)
		}
		a.logger.Error("failed to check phone existence", "error", err)

		return errs.NewAppError(errs.Database, "Failed to check phone existence.", 500)
	}

	if ok, err := a.userRepo.ExistsParticleID(ctx, req.UUID); err != nil || ok {
		if ok {
			return errs.NewAppError(errs.Conflict, "Particle ID already in use, please try to login.", 409)
		}
		a.logger.Error("failed to check particle id existence", "error", err)

		return errs.NewAppError(errs.Database, "Failed to check particle id existence.", 500)
	}

	return nil
}

func (a *AuthService) validateProvisionedUser(ctx context.Context, user *userentity.User) error {
	if user.Type == object.UserTypeOrganization && user.CompanyName == "" {
		return errs.NewAppError(errs.BadRequest, "Organization name is required.", 400)
	}

	if user.Email != "" {
		if ok, err := a.userRepo.ExistsEmail(ctx, user.Email); err != nil || ok {
			if ok {
				return errs.NewAppError(errs.Conflict, "Email already in use, please try to login.", 409)
			}
			a.logger.Error("failed to check email existence", "error", err)

			return errs.NewAppError(errs.Database, "Failed to check email existence.", 500)
		}
	}

	if user.PhoneNumber != "" {
		if ok, err := a.userRepo.ExistsPhone(ctx, user.PhoneNumber); err != nil || ok {
			if ok {
				return errs.NewAppError(errs.Conflict, "Phone number already in use, please try to login.", 409)
			}
			a.logger.Error("failed to check phone existence", "error", err)

			return errs.NewAppError(errs.Database, "Failed to check phone existence.", 500)
		}
	}

	if ok, err := a.userRepo.ExistsOpenfortUserID(ctx, user.OpenfortUserID); err != nil || ok {
		if ok {
			return errs.NewAppError(errs.Conflict, "Openfort user already exists, please try to login.", 409)
		}
		a.logger.Error("failed to check openfort user existence", "error", err)

		return errs.NewAppError(errs.Database, "Failed to check openfort user existence.", 500)
	}

	return nil
}

func (a *AuthService) validateSession(sess *entity.Session) error {
	if sess.IsRevoked() {
		return errs.NewAppError(errs.Unauthorized,
			"Your session was terminated, try to login.", 401)
	}

	if sess.IsAbsolutelyExpired() {
		daysActive := int(time.Since(sess.CreatedAt).Hours() / 24)

		return errs.NewAppError(
			errs.Unauthorized,
			fmt.Sprintf("Your session has expired after %d days of use. Please login again for security.", daysActive),
			401,
		)
	}

	if sess.IsIdleExpired() {
		inactivityMinutes := int(a.cfg.ActivityTimeoutDuration.Minutes())

		return errs.NewAppError(
			errs.Unauthorized,
			"Your session expired due to inactivity after "+strconv.Itoa(inactivityMinutes)+
				" minutes. Please login again.",
			401,
		)
	}

	return nil
}

package input

type OpenfortExchangeInput struct {
	Authorization string               `header:"Authorization" required:"true"`
	Body          OpenfortExchangeBody `json:"body"`
}

type OpenfortExchangeBody struct {
	FirstName        string `json:"first_name" required:"false" maxLength:"100" example:"John"`
	LastName         string `json:"last_name" required:"false" maxLength:"100" example:"Doe"`
	OrganizationName string `json:"organization_name" required:"false" maxLength:"255" example:"Acme Corp"`
	PhoneNumber      string `json:"phone_number" required:"false" maxLength:"20" example:"+1234567890"`
	Email            string `json:"email" required:"false" maxLength:"255" example:"example@gmail.com"`
	Type             string `json:"type" required:"false" enum:"individual,organization" example:"individual"`
	Role             string `json:"role" required:"false" enum:"project_owner,investor,contractor,governance" example:"investor"`
}

type CurrentUserInput struct{}

type RegistrationInput struct {
	Body RegistrationBody
}

type RegistrationBody struct {
	UUID             string `json:"uuid" minLength:"1" required:"true" maxLength:"100" example:"123e4567-e89b-12d3-a456-426614174000"`
	Token            string `json:"token" minLength:"1" required:"true" maxLength:"255" example:"registration_token"`
