)

type Application struct {
	cfg *config.Config
	app *fx.App
	db  *postgres.Database
}

func New(cfg *config.Config) (*Application, error) {
	logger.InitGlobalLogger(cfg.Logger)
	logger.Info("Initializing application", "environment", cfg.Environment)

	if err := os.MkdirAll(cfg.DataDir, 0o750); err != nil {
		return nil, fmt.Errorf("failed to create data directory: %w", err)
	}

	app := &Application{
		cfg: cfg,
	}

	cfg.Rest.Development = cfg.Environment == environment.Development

	fxApp := fx.New(
		// Supply configs
		fx.Supply(cfg.Postgres),
		fx.Supply(cfg.Rest),
		fx.Supply(cfg.ContactForm),
		fx.Supply(cfg.DataDir),
		fx.Supply(cfg.Auth),
		fx.Supply(cfg.Auth.Jwt),
		fx.Supply(cfg.Auth.Openfort),
		fx.Supply(20*time.Second), // Readiness timeout
		fx.Supply(cfg.Environment == environment.Development),

		// Provide constructors
		fx.Provide(readiness.NewReadinessManager),
		fx.Provide(postgres.New),
		fx.Provide(openfort.New),
		fx.Provide(rest.New),
		fx.Provide(func(db *postgres.Database) shared.Transactor {
			return db.Tx()
		}),

		// Provide layers
		app.initRepoModule(),
		app.initServiceModule(),
		app.initSchedulerModule(),
		app.initHandlerModule(),
		app.initRouterModule(),

		// Force construction and retain db reference
		fx.Invoke(func(
			db *postgres.Database,
			openfort openfort.SessionVerifier,
			_ *rest.Rest,
			readMgr *readiness.Manager,
		) {
			app.db = db

			// Register external service health check
			readMgr.Register(db)
			readMgr.Register(openfort)
		}),
		fx.NopLogger,
	)

	app.app = fxApp

	logger.Info("Application initialized successfully")

	return app, nil
}

func (a *Application) Start(ctx context.Context) error {
	logger.Info("Starting application...")

	if err := a.app.Start(ctx); err != nil {
		return fmt.Errorf("failed to start application: %w", err)
	}

	logger.Info("Application started and ready to accept connections")

	return nil
}

func (a *Application) Stop(ctx context.Context) error {
	logger.Warn("Stopping application...")

	stopCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()

	if err := a.app.Stop(stopCtx); err != nil {
		return fmt.Errorf("failed to stop application gracefully: %w", err)
	}

	logger.Info("Application stopped successfully")

	return nil
}

func (*Application) initRepoModule() fx.Option {
	return fx.Module("repository",
		fx.Provide(
			fx.Annotate(
				postgres.NewWaitlistRepo,
				fx.As(new(waitlistrepo.WaitlistRepo)),
			),
			fx.Annotate(
				postgres.NewContactFormRepo,
				fx.As(new(cfrepo.ContactFormRepo)),
			),
			fx.Annotate(
				postgres.NewLocationRepo,
				fx.As(new(corepo.LocationRepo)),
			),
			fx.Annotate(
				postgres.NewNonResidentWaitlistRepo,
				fx.As(new(nrwrepo.NonResidentWaitListRepo)),
			),
			fx.Annotate(
				postgres.NewSessionRepo,
				fx.As(new(sessrepo.SessionRepo)),
			),
			fx.Annotate(
				postgres.NewUserRepo,
				fx.As(new(userrepo.UserRepo)),
			),
			fx.Annotate(
				postgres.NewWalletRepo,
				fx.As(new(walrepo.WalletRepo)),
			),
			fx.Annotate(
				postgres.NewAccountLockoutRepo,
				fx.As(new(repository.AccountLockoutRepo)),
			),
		),
	)
}

func (*Application) initServiceModule() fx.Option {
	return fx.Module("service",
		fx.Provide(
			fx.Annotate(
				waitlist.NewWaitlistService,
				fx.As(new(waitlistsvc.WaitListService)),
			),
			fx.Annotate(
				contact_form.NewContactFormService,
				fx.As(new(cfsvc.ContactFormService)),
			),
			fx.Annotate(
				location.NewLocationService,
				fx.As(new(cosvc.LocationService)),
			),
			fx.Annotate(
				non_resident_waitlist.NewNonResidentWaitlistService,
				fx.As(new(nrwcsvc.NonResidentWaitListService)),
			),
			fx.Annotate(
				auth.NewOpenfortAuthService,
				fx.As(new(authsvc.AuthService)),
			),
			fx.Annotate(
				auth.NewJwtService,
				fx.As(new(authsvc.JwtService)),
			),
			crypto.New,
			fx.Annotate(
				auth.NewAccountLockoutService,
				fx.As(new(authsvc.AccountLockoutService)),
			),
		),
	)
}

func (*Application) initSchedulerModule() fx.Option {
	return fx.Module("scheduler",
		fx.Provide(
			fx.Annotate(
				auth.NewAccountLockoutScheduler,
				fx.As(new(authsvc.AccountLockoutScheduler)),
			),
		),
		fx.Invoke(func(_ authsvc.AccountLockoutScheduler) {}),
	)
}

func (*Application) initHandlerModule() fx.Option {
	return fx.Module("handler",
		fx.Provide(
			handler.NewWaitlistHandler,
			handler.NewContactFormHandler,
			handler.NewLocationHandler,
			handler.NewNonResidentWaitlistHandler,
			handler.NewAuthHandler,
		),
	)
}

func (*Application) initRouterModule() fx.Option {
	return fx.Module("router",
		fx.Provide(
			func(rest *rest.Rest) *fiber.App {
				return rest.App()
			},
		),
		fx.Invoke(router.NewRouter),
	)
}

