func (i *integration) generateUser(opts ...userOpt) uuid.UUID {
	userRepo := postgres.NewUserRepo(i.DB)
	walRepo := postgres.NewWalletRepo(i.DB)

	ctx := context.Background()

	usr := &entity.User{
		ParticleID:  gofakeit.UUID(),
		Email:       shared.NewEmail(gofakeit.Email()),
		FirstName:   gofakeit.FirstName(),
		LastName:    gofakeit.LastName(),
		PhoneNumber: shared.NewPhoneNumber(gofakeit.Phone()),
		Type:        object.UserTypeIndividual,
		Role:        object.UserRoleInvestor,
		Status:      object.UserStatusActive,
	}

	for _, opt := range opts {
		opt(usr)
	}

	userID, err := userRepo.Create(ctx, usr)
	require.NoError(i.T(), err)
	require.NotEmpty(i.T(), userID)

	walletAddr := fmt.Sprintf("0x%s", gofakeit.HexUint(40)) // 0x + 40 random hex chars

	count, err := walRepo.CreateBatchWallets(context.Background(), []*walentity.Wallet{
		{
			UserID:        userID,
			PublicAddress: walletAddr,         // Unique!
			Chain:         walletobj.EVMChain, // Use enum value
		},
	})
	require.NoError(i.T(), err)
	require.Equal(i.T(), int64(1), count)

	return userID
}


