package openfort

import "errors"

type Config struct {
	PublishableKey string `koanf:"publishable_key"`

	BaseURL string `koanf:"-"`
}

func DefaultConfig() *Config {
	return &Config{
		BaseURL: "https://api.openfort.io",
	}
}

func (c *Config) BasicCheck() error {
	if c.PublishableKey == "" {
		return errors.New("openfort publishable_key is required")
	}

	return nil
}

