	@echo "$(COLOR_BLUE)→ Running linter...$(COLOR_RESET)"
	@golangci-lint run --timeout=20m
	@echo "$(COLOR_GREEN)✓ Linting passed$(COLOR_RESET)"

.PHONY: lint-fix
